package com.ventas.service;
import com.ventas.dto.SettingsModels.*;import com.ventas.repository.SettingsRepository;import com.ventas.security.*;import com.ventas.security.AuthModels.Identity;import com.fasterxml.jackson.databind.ObjectMapper;
import java.math.BigDecimal;import java.time.*;import java.util.*;import java.util.function.Supplier;
import org.junit.jupiter.api.*;import org.springframework.transaction.support.*;
import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;
class SettingsServiceTest{
 SettingsRepository repo;BusinessTransactions tx;SettingsService service;LocalDateTime version=LocalDateTime.of(2026,10,24,12,0);
 Identity actor=new Identity(1,"admin.test","N","A","ADM",false,Set.of("CFG.PARAMETROS","CFG.TICKET","CFG.SERIES","CFG.ETIQUETAS"),UUID.randomUUID(),OffsetDateTime.now().plusHours(1));
 Parameter parameter(String key,String value){return new Parameter(key,"VENTAS",value,"ENTERO",BigDecimal.ONE,new BigDecimal(180),"Plazo",true,version);}
 @BeforeEach void setup(){repo=mock(SettingsRepository.class);tx=mock(BusinessTransactions.class);TransactionTemplate transaction=mock(TransactionTemplate.class);when(transaction.execute(any())).thenAnswer(i->((TransactionCallback<?>)i.getArgument(0)).doInTransaction(mock(org.springframework.transaction.TransactionStatus.class)));when(tx.write(any(),anyString(),anyString(),any())).thenAnswer(i->((Supplier<?>)i.getArgument(3)).get());when(repo.admin(1)).thenReturn(true);when(repo.parameters(anyBoolean())).thenReturn(List.of());service=new SettingsService(repo,tx,transaction,new ObjectMapper().findAndRegisterModules());}
 Changes change(String key,String value,LocalDateTime v){return new Changes(List.of(new Change(key,value,v)));}
 @Test void noAccessWithoutPermission(){Identity denied=new Identity(1,"test","N","A","ADM",false,Set.of(),actor.sessionToken(),actor.expiraEn());assertThatThrownBy(()->service.parameters(denied,false)).isInstanceOf(AuthFailure.class);verifyNoInteractions(repo);}
 @Test void onlyAllowedKeysAreExposed(){when(repo.parameters(false)).thenReturn(List.of(parameter("SMTP.PASSWORD","privado"),parameter("VENTAS.PLAZO_CREDITO_DIAS","30")));assertThat(service.parameters(actor,false)).hasSize(1).allMatch(p->p.editable());}
 @Test void unimplementedFeaturesCannotBeEnabled(){assertThatThrownBy(()->service.save(actor,"local",true,change("COMPROBANTE.EMISION_ELECTRONICA","1",version))).isInstanceOf(AuthFailure.class);verify(repo,never()).value(any(),any());}
 @Test void staleParameterIsRejected(){when(repo.parameter(anyString(),eq(true))).thenReturn(Optional.of(parameter("VENTAS.PLAZO_CREDITO_DIAS","30")));assertThatThrownBy(()->service.save(actor,"local",false,change("VENTAS.PLAZO_CREDITO_DIAS","45",version.minusSeconds(1)))).isInstanceOf(AuthFailure.class);verify(repo,never()).value(any(),any());}
 @Test void invalidNumberAndRangeAreRejected(){Parameter p=parameter("VENTAS.PLAZO_CREDITO_DIAS","30");for(String value:List.of("NaN","1.5","0","181","1e2"))assertThatThrownBy(()->service.validate(p,value)).isInstanceOf(AuthFailure.class);}
 @Test void validatesBusinessFieldsAndFormats(){for(var p:List.of(parameter("NEGOCIO.RUC",""),parameter("COMPROBANTE.FORMATO",""),parameter("COMPROBANTE.TAMANO_TEXTO","")))assertThatThrownBy(()->service.validate(p,"incorrecto")).isInstanceOf(AuthFailure.class);}
 @Test void createsOnlyTheControlledPrintPreference(){when(repo.parameter("COMPROBANTE.TAMANO_TEXTO",true)).thenReturn(Optional.empty());when(repo.parameter("COMPROBANTE.TAMANO_TEXTO",false)).thenReturn(Optional.of(new Parameter("COMPROBANTE.TAMANO_TEXTO","COMPROBANTE","GRANDE","TEXTO",null,null,"Tamaño",true,version)));service.save(actor,"local",true,change("COMPROBANTE.TAMANO_TEXTO","GRANDE",null));verify(repo).createTextSize("GRANDE");verify(repo).audit(eq(1L),eq("CFG.TICKET"),eq("parametro_sistema"),isNull(),anyString(),anyString());}
 @Test void unchangedValueDoesNotWrite(){Parameter p=parameter("VENTAS.PLAZO_CREDITO_DIAS","30");when(repo.parameter(p.clave(),true)).thenReturn(Optional.of(p));service.save(actor,"local",false,change(p.clave(),"30",version));verify(repo,never()).value(any(),any());verify(repo,never()).audit(anyLong(),any(),any(),any(),any(),any());}
 Series series(boolean used){return new Series(2,"B","B002",1,used?5:0,"A",used,version);}
 @Test void usedSeriesCannotBeReinterpreted(){when(repo.series(2,true)).thenReturn(Optional.of(series(true)));assertThatThrownBy(()->service.update(actor,"local",2,new SeriesInput("B","B003",1,version))).isInstanceOf(AuthFailure.class);verify(repo,never()).editSeries(anyLong(),any());}
 @Test void lastActiveSeriesCannotBeDisabled(){when(repo.series(2,true)).thenReturn(Optional.of(series(false)));when(repo.otherActive("B",2)).thenReturn(0L);assertThatThrownBy(()->service.state(actor,"local",2,new State("I",version))).isInstanceOf(AuthFailure.class);verify(repo,never()).state(anyLong(),any());}
 @Test void initialNumberCannotGoBackwards(){when(repo.series(2,true)).thenReturn(Optional.of(new Series(2,"B","B002",10,9,"A",false,version)));assertThatThrownBy(()->service.update(actor,"local",2,new SeriesInput("B","B002",1,version))).isInstanceOf(AuthFailure.class);}
 @Test void seriesPrefixMustMatchDocumentType(){assertThatThrownBy(()->service.create(actor,"local",new SeriesInput("B","F002",1,null))).isInstanceOf(AuthFailure.class);verify(repo,never()).createSeries(any());}
 @Test void labelsMustUseRegisteredPresentation(){when(repo.label(any())).thenReturn(Optional.empty());assertThatThrownBy(()->service.label(actor,"local",new LabelRequest(1,2,null,5))).isInstanceOf(AuthFailure.class);}
 @Test void labelGenerationIsAudited(){when(repo.label(any())).thenReturn(Optional.of(new Label("Producto","Unidad","PRO-001","CODE128","5.00",2)));assertThat(service.label(actor,"local",new LabelRequest(1,2,null,2)).cantidad()).isEqualTo(2);verify(repo).audit(eq(1L),eq("CFG.ETIQUETAS"),eq("presentacion_producto"),eq(2L),isNull(),anyString());}
}
